   168  static int jsmn_parse_string(jsmn_parser *parser, const char *js,
   169                  size_t len, jsmntok_t *tokens, size_t num_tokens) {
   170          jsmntok_t *token;
   171
   172          int start = parser->pos;
   173
   174          parser->pos++;
   175
   176          /* Skip starting quote */
   177          for (; parser->pos < len && js[parser->pos] != '\0'; parser->pos++) {
   178                  char c = js[parser->pos];
   179
   180                  /* Quote: end of string */
   181                  if (c == '\"') {
   182                          if (tokens == NULL) {
   183                                  return 0;
   184                          }
   185                          token = jsmn_alloc_token(parser, tokens, num_tokens);
   186                          if (token == NULL) {
   187                                  parser->pos = start;
   188                                  return JSMN_ERROR_NOMEM;
   189                          }
   190                          jsmn_fill_token(token, JSMN_STRING, start+1, parser->pos);
   191  #ifdef JSMN_PARENT_LINKS
   192                          token->parent = parser->toksuper;
   193  #endif
   194                          return 0;
   195                  }
   196
   197                  /* Backslash: Quoted symbol expected */
   198                  if (c == '\\' && parser->pos + 1 < len) {
   199                          int i;
   200                          parser->pos++;
   201                          switch (js[parser->pos]) {
   202                                  /* Allowed escaped symbols */
   203                                  case '\"': case '/' : case '\\' : case 'b' :
   204                                  case 'f' : case 'r' : case 'n'  : case 't' :
   205                                          break;
   206                                  /* Allows escaped symbol \uXXXX */
   207                                  case 'u':
   208                                          parser->pos++;
   209                                          for(i = 0; i < 4 && parser->pos < len && js[parser->pos] != '\0'; i++) {
   210                                                  /* If it isn't a hex character we have an error */
   211                                                  if(!((js[parser->pos] >= 48 && js[parser->pos] <= 57) || /* 0-9 */
   212                                                                          (js[parser->pos] >= 65 && js[parser->pos] <= 70) || /* A-F */
   213                                                                          (js[parser->pos] >= 97 && js[parser->pos] <= 102))) { /* a-f */
   214                                                          parser->pos = start;
   215                                                          return JSMN_ERROR_INVAL;
   216                                                  }
   217                                                  parser->pos++;
   218                                          }
   219                                          parser->pos--;
   220                                          break;
